/**
 * The font catalogue: metadata for every bundled family, available immediately (no font file is touched). Font files are
 * loaded lazily by the FontService. The data in catalog.json is generated by scripts/fetch-fonts.mjs, which also verifies each
 * family's licence against an allow-list and records its source and the date it was checked.
 */
import raw from './catalog.json';

export type FontCategoryId = 'chunky' | 'arcade' | 'comic' | 'condensed' | 'rounded' | 'fantasy' | 'horror' | 'scifi' | 'western' | 'elegant';
export type FontStyle = 'normal' | 'italic';

export interface FontCategory { id: FontCategoryId; name: string }
export interface FontFile { file: string; weight: number; style: FontStyle; bytes: number; sha256: string }
export interface FontFamilyMeta {
  /** Stable id (Fontsource slug), used in presets. */
  id: string;
  /** Real family name, shown to people. */
  family: string;
  category: FontCategoryId;
  /** Weights bundled with the playground (a family appears once however many weights it has). */
  weights: number[];
  allWeights: number[];
  styles: FontStyle[];
  files: FontFile[];
  source: string;
  sourceUrl: string;
  licenseId: string;
  licenseName: string;
  licenseUrl: string;
  /** Path of the licence text inside an exported bundle's fonts folder. */
  licenseFile: string;
  copyright: string;
  redistributionPermitted: boolean;
  redistributionNote: string;
  fontVersion: string;
  dateChecked: string;
}

interface CatalogJson { generated: string; categories: FontCategory[]; families: FontFamilyMeta[] }
const data = raw as unknown as CatalogJson;

export const FONT_CATEGORIES: readonly FontCategory[] = data.categories;
export const FONT_FAMILIES: readonly FontFamilyMeta[] = data.families;
export const FONT_CATALOG_GENERATED = data.generated;

const byId = new Map(FONT_FAMILIES.map((f) => [f.id, f]));
const byName = new Map(FONT_FAMILIES.map((f) => [f.family.toLowerCase(), f]));

export const getFamily = (idOrName: string): FontFamilyMeta | undefined => byId.get(idOrName) ?? byName.get(idOrName.toLowerCase());
export const isCatalogFont = (id: string): boolean => byId.has(id);

/** What a text style stores about its font. Weight and style are choices within ONE family. */
export interface FontSpec { id: string; weight: number; style: FontStyle }

export const DEFAULT_FONT: FontSpec = { id: 'lilita-one', weight: 400, style: 'normal' };

/** The bundled file for (family, weight, style): exact when it exists, otherwise the closest available (`exact: false`). */
export function pickFile(meta: FontFamilyMeta, weight: number, style: FontStyle): { file: FontFile; exact: boolean } {
  const exact = meta.files.find((f) => f.weight === weight && f.style === style);
  if (exact) return { file: exact, exact: true };
  const sameStyle = meta.files.filter((f) => f.style === style);
  const pool = sameStyle.length ? sameStyle : meta.files;
  let best = pool[0]!;
  for (const f of pool) if (Math.abs(f.weight - weight) < Math.abs(best.weight - weight)) best = f;
  return { file: best, exact: false };
}

export interface FontQuery { text?: string; category?: FontCategoryId | 'all'; ids?: ReadonlySet<string> }

/** Search by name/category words; every query word must match. */
export function searchFonts(q: FontQuery = {}): FontFamilyMeta[] {
  const words = (q.text ?? '').toLowerCase().split(/\s+/).filter(Boolean);
  const catName = new Map(FONT_CATEGORIES.map((c) => [c.id, c.name.toLowerCase()]));
  return FONT_FAMILIES.filter((f) => {
    if (q.category && q.category !== 'all' && f.category !== q.category) return false;
    if (q.ids && !q.ids.has(f.id)) return false;
    if (!words.length) return true;
    const hay = `${f.family} ${f.id} ${catName.get(f.category)} ${f.licenseId}`.toLowerCase();
    return words.every((w) => hay.includes(w));
  });
}

export const fontCategoryName = (id: FontCategoryId): string => FONT_CATEGORIES.find((c) => c.id === id)?.name ?? id;
